def design(k0,k1,k2,k3):
    cols=[np.ones_like(t),1-np.exp(-k0*t),P,P*(1-np.exp(-k1*t)),P**2,P**2*(1-np.exp(-k2*t)),P**3,P**3*(1-np.exp(-k3*t))]
    return np.column_stack(cols)
def err(ks):
    A=design(*ks)
    c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
    return np.mean((y-A@c)**2)/np.var(y), c
