        c,_,_,_=np.linalg.lstsq(A,y,rcond=None)
        e=np.mean((y-A@c)**2)/np.var(y)
        if best is None or e<best[0]: best=(e,i)
    sel.append(best[1])
    print(step, names[best[1]], round(best[0],9))
